package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalDigitValueTest {
 @Test public void publicDigitAndValueAreDistinctAndIgnoreKeys(){for(String[] c:new String[][]{{"54.321","십의 자리","5","50"},{"54.321","일의 자리","4","4"},{"54.321","소수 셋째 자리","1","0.001"},{"0.007","소수 셋째 자리","7","0.007"},{"10.00","소수 둘째 자리","0","0"},{"4.5","소수 첫째 자리","5","0.5"}}){Question q=new Question(DecimalPlaceRelations.ID,c[0]+"의 "+c[1]+" 숫자와 그 숫자가 나타내는 값을 쓰세요.","poison","999","999");assertTrue(new Checker().check(q,List.of(),List.of(c[2],c[3])).correct());assertEquals(1,new Checker().check(q,List.of(),List.of(c[2],"999")).index);assertEquals(4,HelpPlan.forQuestion(q).size());assertFalse(HelpPlan.forQuestion(q).canTransfer());}assertNull(DecimalPlaceRelations.read(new Question(DecimalPlaceRelations.ID,"0.007의 십의 자리 숫자와 그 숫자가 나타내는 값을 쓰세요.","","0","0")));}
 @Test public void actualNaSixUsesEveryDisplayedPrecisionAndPositionWithoutNarrowingLegacy(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(DecimalPlaceRelations.ID,6));var l=GlobalCurriculum.limits(pack.id,DecimalPlaceRelations.ID,6);assertEquals(531900,DecimalPlaceRelations.count(l));Generator g=new Generator(new Random(289));List<String> history=new ArrayList<>();Set<Integer> positions=new HashSet<>(),places=new HashSet<>();boolean overNine=false;for(int i=0;i<300;i++){Question q=g.next(DecimalPlaceRelations.ID,history,false,l);assertFalse(history.contains(q.signature()));history.add(q.signature());var v=DecimalPlaceRelations.read(q);assertNotNull(v);positions.add(v.position());places.add(v.raw().length()-v.raw().indexOf('.')-1);overNine|=new java.math.BigDecimal(v.raw()).compareTo(java.math.BigDecimal.TEN)>=0;assertTrue(l.allows(q));assertTrue(new Checker().check(q,List.of(),List.of(""+v.digit(),v.value().toPlainString())).correct());}assertTrue(overNine);assertEquals(Set.of(-1,0,1,2,3),positions);assertEquals(Set.of(1,2,3),places);assertEquals(3000,DecimalPlaceRelations.count(GlobalCurriculum.limits("england-primary-2021-v1",DecimalPlaceRelations.ID,4)));}
}
